export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const format=(n,d=1)=>Number.isFinite(n)?n.toLocaleString('es-ES',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
const colors=['#087f7a','#d88a39','#596a82','#906cbd','#377fb0','#ac6671'];
export function chart(node,title,series,xlabel,ylabel,{marker=null,xmax=null,zero=true}={}){if(!node)return;const W=530,H=250,p={l:55,r:19,t:22,b:43};let points=series.flatMap(s=>s.x.map((x,i)=>[x,s.y[i]]).filter(([x,y])=>Number.isFinite(x)&&Number.isFinite(y)));if(!points.length)points=[[0,0],[1,1]];const maxX=xmax??points.reduce((v,p)=>Math.max(v,p[0]),1),minY=points.reduce((v,p)=>Math.min(v,p[1]),zero?0:Infinity),maxY=points.reduce((v,p)=>Math.max(v,p[1]),minY+1)*1.07;const X=x=>p.l+x/maxX*(W-p.l-p.r),Y=y=>H-p.b-(y-minY)/(maxY-minY)*(H-p.t-p.b);let grid='';for(let j=0;j<=5;j++){const x=j*maxX/5,y=minY+j*(maxY-minY)/5;grid+=`<line x1="${X(x)}" y1="${p.t}" x2="${X(x)}" y2="${H-p.b}" stroke="#e8eef0"/><line x1="${p.l}" y1="${Y(y)}" x2="${W-p.r}" y2="${Y(y)}" stroke="#e8eef0"/><text x="${X(x)}" y="${H-p.b+19}" text-anchor="middle">${format(x,maxX<10?1:0)}</text><text x="${p.l-9}" y="${Y(y)+4}" text-anchor="end">${format(y,maxY<10?1:0)}</text>`;}
 const id='clip-'+Math.random().toString(36).slice(2);const paths=series.map((s,j)=>{const skip=Math.max(1,Math.floor(s.x.length/700));let d='';for(let i=0;i<s.x.length;i+=skip)if(Number.isFinite(s.x[i])&&Number.isFinite(s.y[i]))d+=`${d?'L':'M'}${X(s.x[i]).toFixed(2)},${Y(s.y[i]).toFixed(2)} `;if(s.x.length)d+=`L${X(s.x.at(-1))},${Y(s.y.at(-1))}`;return `<path d="${d}" fill="none" stroke="${s.color||colors[j%colors.length]}" stroke-width="${s.dash?1.7:2.4}" ${s.dash?'stroke-dasharray="6 4"':''} stroke-linecap="round"/>`;}).join('');
 node.className='chart-card';node.innerHTML=`<div class="chart-heading"><h3>${escape(title)}</h3><button class="icon export-chart" title="Descargar gráfico SVG" aria-label="Descargar ${escape(title)} en SVG">SVG</button></div><div class="chart-plot"><svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${escape(title)}. ${escape(xlabel)} frente a ${escape(ylabel)}"><defs><clipPath id="${id}"><rect x="${p.l}" y="${p.t}" width="${W-p.l-p.r}" height="${H-p.t-p.b}"/></clipPath></defs>${grid}<text x="${(p.l+W-p.r)/2}" y="${H-5}" text-anchor="middle">${escape(xlabel)}</text><text transform="translate(14 ${(p.t+H-p.b)/2}) rotate(-90)" text-anchor="middle">${escape(ylabel)}</text><g clip-path="url(#${id})">${paths}${marker?`<circle cx="${X(marker[0])}" cy="${Y(marker[1])}" r="4.5" fill="#db8c3a" stroke="white" stroke-width="1.5"/>`:''}<line class="crosshair" y1="${p.t}" y2="${H-p.b}" stroke="#7c929c" stroke-dasharray="3 3" visibility="hidden"/></g></svg><div class="tooltip"></div></div><div class="legend">${series.map((s,j)=>`<span><i style="border-color:${s.color||colors[j%colors.length]};border-top-style:${s.dash?'dashed':'solid'}"></i>${escape(s.name)}</span>`).join('')}</div>`;
 const svg=node.querySelector('svg'),tooltip=node.querySelector('.tooltip'),cross=node.querySelector('.crosshair');svg.addEventListener('pointermove',e=>{const rect=svg.getBoundingClientRect(),sx=(e.clientX-rect.left)/rect.width*W,q=(sx-p.l)/(W-p.l-p.r)*maxX;if(q<0||q>maxX)return;cross.setAttribute('x1',X(q));cross.setAttribute('x2',X(q));cross.setAttribute('visibility','visible');tooltip.innerHTML=series.map((s,j)=>{let best=0;for(let i=1;i<s.x.length;i++)if(Math.abs(s.x[i]-q)<Math.abs(s.x[best]-q))best=i;return `${escape(s.name)}: ${format(s.y[best],2)}`;}).join('<br>');tooltip.style.display='block';tooltip.style.left=Math.min(e.clientX-rect.left+10,Math.max(0,rect.width-220))+'px';tooltip.style.top='12px';});svg.addEventListener('pointerleave',()=>{tooltip.style.display='none';cross.setAttribute('visibility','hidden');});node.querySelector('.export-chart').onclick=()=>{const clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.querySelector('.crosshair').remove();download(new XMLSerializer().serializeToString(clone),title.replaceAll(' ','_')+'.svg','image/svg+xml');};
}
export function download(content,name,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function metric(caption,value,unit,note='',accent=false){return `<div class="metric ${accent?'accent':''}"><div class="caption">${escape(caption)}</div><strong>${value}<small>${escape(unit)}</small></strong><div class="note">${escape(note)}</div></div>`;}
